'use strict';
/* ============ ATTENDANCE & LEAVE ============ */
function shiftOf(rec) { const e = emp(rec.empId); return D.shifts.map[rec.shiftId] || D.shifts.map[e?.shiftId]; }
function attCalc(rec) {
  const sh = shiftOf(rec); const out = { late: 0, early: 0, ot: 0, sh };
  if (!sh) return out;
  const st = toMin(sh.start), en = toMin(sh.end), grace = Number(sh.grace ?? SET().graceMin ?? 0), otMin = Number(SET().otThresholdMin ?? 30);
  const i = toMin(rec.in), o = toMin(rec.out);
  if (i != null && st != null && i > st + grace) out.late = i - st;
  if (o != null && en != null && o < en) out.early = en - o;
  if (o != null && en != null && o - en >= otMin) out.ot = o - en;
  return out;
}
function attTable(rows, manage) {
  if (!rows.length) return empty('لا توجد سجلات حضور في هذه الفترة');
  return `<div class="tablewrap"><table><thead><tr><th>التاريخ</th>${manage ? '<th>الموظف</th>' : ''}<th>الوردية</th><th>الحضور</th><th>الانصراف</th><th>التأخير (د)</th><th>خروج مبكر (د)</th><th>إضافي (د)</th><th>المصدر</th>${manage ? '<th></th>' : ''}</tr></thead><tbody>${rows.map(r => { const c = attCalc(r); return `<tr><td class="num">${fmtD(r.date)}</td>${manage ? `<td>${esc(empName(r.empId))}</td>` : ''}<td>${esc(c.sh?.name || '—')}</td><td class="num">${esc(r.in || '—')}</td><td class="num">${esc(r.out || '—')}</td><td class="num">${c.late ? `<b style="color:var(--warn)">${c.late}</b>` : '0'}</td><td class="num">${c.early || 0}</td><td class="num">${c.ot || 0}</td><td class="small muted">${esc(r.source || '')}</td>${manage ? `<td><button class="btn sm ghost" data-act="att-edit" data-id="${r.id}">تعديل</button></td>` : ''}</tr>`; }).join('')}</tbody></table></div>`;
}
function onLeave(empId, date) { return D.requests.list.some(r => r.empId === empId && r.effect === 'leave' && r.status === 'approved' && r.data?.from <= date && r.data?.to >= date); }
function monthly(month, empIds) {
  const [y, m] = month.split('-').map(Number); const last = new Date(y, m, 0).getDate(); const t = todayISO(); const wk = SET().weekend || [5, 6];
  const days = []; for (let d = 1; d <= last; d++) { const iso = `${month}-${String(d).padStart(2, '0')}`; if (iso > t) break; if (!wk.includes(new Date(iso + 'T00:00:00').getDay()) && !isHoliday(iso)) days.push(iso); }
  return empIds.map(id => {
    const e = emp(id); const recs = D.attendance.list.filter(a => a.empId === id && a.date?.startsWith(month));
    let late = 0, lateMin = 0, ot = 0, early = 0; recs.forEach(r => { const c = attCalc(r); if (c.late) { late++; lateMin += c.late; } ot += c.ot; early += c.early; });
    const present = new Set(recs.filter(r => r.in).map(r => r.date));
    const valid = days.filter(d => (!e.joinDate || d >= e.joinDate) && (!e.lastDay || d <= e.lastDay));
    const leave = valid.filter(d => onLeave(id, d)).length; const absent = valid.filter(d => !present.has(d) && !onLeave(id, d)).length;
    return { id, name: e.nameAr, dept: unitName(e.deptId), loc: unitName(e.locationId), shift: D.shifts.map[e.shiftId]?.name || '—', work: valid.length, present: present.size, leave, absent, late, lateMin, early, ot: Math.round(ot / 6) / 10 };
  });
}
