/* ============ PAYROLL ============ */
const elTotal = s => s ? ['basic', 'housing', 'transport', 'other'].reduce((a, k) => a + Number(s[k] || 0), 0) : 0;
function loanDue(l, month) { return l.status === 'open' && month >= (l.startMonth || '') && !(l.paid || []).includes(month) && (l.paid || []).length < l.installments; }
function payrollSheet(month) {
  const st = SET(); const otOn = st.otRate && st.monthHours;
  return D.employees.list.filter(e => e.status !== 'terminated' && (!e.joinDate || e.joinDate.slice(0, 7) <= month)).map(e => {
    const s = D.salaries.map[e.id]; const gross = elTotal(s);
    const loan = D.loans.list.filter(l => l.empId === e.id && loanDue(l, month)).reduce((a, l) => a + Number(l.monthly || 0), 0);
    const adj = D.adjustments.list.filter(a => a.empId === e.id && a.month === month && a.status === 'approved');
    const bonus = adj.filter(a => a.kind === 'bonus').reduce((x, a) => x + Number(a.amount), 0), ded = adj.filter(a => a.kind === 'deduction').reduce((x, a) => x + Number(a.amount), 0);
    let otPay = 0, otH = 0; if (otOn && s) { otH = monthly(month, [e.id])[0].ot; otPay = Math.round(otH * (Number(s.basic || 0) / Number(st.monthHours)) * Number(st.otRate) * 100) / 100; }
    return { id: e.id, empNo: e.empNo, name: e.nameAr, cc: unitName(e.costCenterId), gross, otH, otPay, bonus, ded, loan, net: gross + otPay + bonus - ded - loan, missing: !s };
  });
}
