/* ============ REPORTS ============ */
function cycleHours(rs) { const c = rs.filter(r => r.closedAt && r.status !== 'cancelled'); if (!c.length) return null; return c.reduce((a, r) => a + (new Date(r.closedAt) - new Date(r.createdAt)) / 36e5, 0) / c.length; }
VIEWS.reports = () => {
  const items = [...(can('reports.exec') ? [['exec', 'الإدارة العليا']] : []), ...(can('reports.hr') ? [['hr', 'الموارد البشرية']] : []), ...(can('team.view') ? [['mgr', 'لوحة المدير']] : []), ...(can('admin.services') ? [['adm', 'الشؤون الإدارية']] : [])];
  if (!items.length) return empty('لا توجد لوحات متاحة لدورك');
  const t = tabs('rep', items); const T = todayISO(); const month = monthISO(); const active = D.employees.list.filter(e => e.status !== 'terminated');
  const last12 = addDays(T, -365); let body = '';
  const countBy = (arr, f) => { const m = {}; arr.forEach(x => { const k = f(x); m[k] = (m[k] || 0) + 1; }); return Object.entries(m).sort((a, b) => b[1] - a[1]); };
  if (t.cur === 'exec') {
    const mon = monthly(month, active.map(e => e.id)); const sum = k => mon.reduce((a, r) => a + r[k], 0);
    const hires = D.employees.list.filter(e => e.hireDate && e.hireDate >= last12).length; const terms = D.employees.list.filter(e => e.status === 'terminated' && e.lastDay && e.lastDay >= last12).length;
    const lateAdm = D.requests.list.filter(r => r.category === 'admin' && r.status === 'pending' && (isOverdue(r) || (r.targetDate && r.targetDate < T))).length;
    const ct = cycleHours(D.requests.list.filter(r => r.createdAt >= last12));
    const comp = active.length ? Math.round(active.reduce((a, e) => a + completeness(e), 0) / active.length) : 0;
    const lim = addDays(T, Number(SET().contractAlertDays || 60)); const exp = active.filter(e => (e.contractEnd && e.contractEnd <= lim) || (e.idExpiry && e.idExpiry <= lim)).length;
    const cost = can('pay.view') ? active.reduce((a, e) => a + elTotal(D.salaries.map[e.id]), 0) : null;
    body = `<div class="grid g4">${kpi('إجمالي الموظفين', fmtN(active.length), 'الموظفون بحالة غير «منتهية خدمته» الآن')}${kpi('تعيينات آخر 12 شهرًا', fmtN(hires), 'عدد من تاريخ تعيينهم خلال 365 يومًا')}${kpi('إنهاء خدمة آخر 12 شهرًا', fmtN(terms), 'منتهية خدمتهم وآخر يوم خلال 365 يومًا')}${kpi('تكلفة القوى العاملة الشهرية', cost == null ? 'مقيد' : fmtSAR(cost), 'مجموع عناصر الأجر الثابتة المسجلة؛ لا يشمل التأمينات والتكاليف غير المسجلة')}
    ${kpi('غياب هذا الشهر (أيام)', fmtN(sum('absent')), 'أيام عمل بلا حضور ولا إجازة معتمدة، من بداية الشهر حتى اليوم', sum('absent'))}${kpi('تأخير هذا الشهر (مرات)', fmtN(sum('late')), 'حضور بعد بداية الوردية + السماحية')}${kpi('ساعات إضافية هذا الشهر', fmtN(sum('ot'), 1), 'انصراف بعد نهاية الوردية بأكثر من الحد الأدنى')}${kpi('طلبات إدارية متأخرة', fmtN(lateAdm), 'طلبات الشؤون الإدارية المفتوحة المتجاوزة للموعد المستهدف', lateAdm)}
    ${kpi('متوسط زمن إنجاز المعاملات', ct == null ? '—' : fmtN(ct / 24, 1) + ' يوم', 'متوسط (تاريخ الإغلاق − تاريخ الإنشاء) للطلبات المغلقة في 12 شهرًا')}${kpi('نسبة اكتمال ملفات الموظفين', comp + '%', 'متوسط نسبة الحقول الإلزامية المعبأة (' + REQUIRED_FIELDS.length + ' حقلًا)')}${kpi('عقود ووثائق قريبة الانتهاء', fmtN(exp), 'عقود أو هويات تنتهي خلال ' + (SET().contractAlertDays || 60) + ' يومًا أو انتهت', exp)}${(() => { const n = active.length, sa = active.filter(isSaudi).length; return kpi(LX('نسبة السعودة', 'Saudization ratio'), n ? Math.round(sa / n * 100) + '%' : '—', LX(`${sa} سعودي من ${n} موظف، من حقل الجنسية. لا يحسب نطاق نطاقات.`, `${sa} Saudi of ${n} employees, from the nationality field. Not the Nitaqat band.`)); })()}</div>
    <div class="grid g2" style="margin-top:16px"><section class="card"><h2>القوى العاملة حسب الإدارة</h2>${bars(countBy(active, e => unitName(e.deptId)))}</section><section class="card"><h2>القوى العاملة حسب الموقع</h2>${bars(countBy(active, e => unitName(e.locationId)))}</section></div>
    <p class="small muted">مصدر كل المؤشرات: قاعدة بيانات المنصة الحالية، محسوبة لحظيًا عند فتح الصفحة.</p>`;
  } else if (t.cur === 'hr') {
    const today = D.requests.list.filter(r => r.createdAt && localISO(new Date(r.createdAt)) === T).length;
    const pend = D.requests.list.filter(r => r.status === 'pending'); const over = pend.filter(isOverdue);
    const byA = {}; pend.forEach(r => currentApprovers(r).forEach(id => byA[empName(id)] = (byA[empName(id)] || 0) + 1));
    const lim = addDays(T, Number(SET().contractAlertDays || 60));
    const onLeaveToday = active.filter(e => onLeave(e.id, T));
    const exceptions = D.requests.list.filter(r => r.effect === 'attendanceFix' && r.status === 'pending').length;
    const quality = active.filter(e => completeness(e) < 100).length;
    body = `<div class="grid g4">${kpi('معاملات اليوم', fmtN(today), 'طلبات أُنشئت اليوم')}${kpi('طلبات معلّقة', fmtN(pend.length))}${kpi('متجاوزة للمدة المستهدفة', fmtN(over.length), 'المرحلة الحالية تجاوزت مدة SLA', over.length)}${kpi('في إجازة اليوم', fmtN(onLeaveToday.length))}${kpi('تصحيحات حضور معلقة', fmtN(exceptions))}${kpi('ملفات غير مكتملة', fmtN(quality), 'ملفات ينقصها حقل إلزامي واحد على الأقل', quality)}${kpi('تحت إجراءات إنهاء الخدمة', fmtN(D.employees.list.filter(e => e.status === 'terminating').length))}${kpi('في فترة التجربة', fmtN(active.filter(e => e.status === 'probation').length))}</div>
    <div class="grid g2" style="margin-top:16px"><section class="card"><h2>الطلبات المعلقة حسب المسؤول</h2>${bars(Object.entries(byA).sort((a, b) => b[1] - a[1]))}</section>
    <section class="card"><h2>عقود ووثائق تحتاج متابعة</h2><div class="list">${active.filter(e => (e.contractEnd && e.contractEnd <= lim) || (e.idExpiry && e.idExpiry <= lim)).map(e => `<div><div class="grow"><a href="#" data-act="go" data-v="employee" data-id="${e.id}">${esc(e.nameAr)}</a><div class="small muted">${e.contractEnd && e.contractEnd <= lim ? 'العقد: ' + fmtD(e.contractEnd) : ''} ${e.idExpiry && e.idExpiry <= lim ? 'الهوية: ' + fmtD(e.idExpiry) : ''}</div></div></div>`).join('') || empty('لا يوجد')}</div></section>
    <section class="card"><h2>الطلبات المتجاوزة للمدة</h2><div class="list">${over.map(r => `<div><div class="grow"><b class="num">${esc(r.ref)}</b> ${esc(r.typeName)}<div class="small muted">${esc(empName(r.empId))} · ${esc(r.stages[r.current].name)}</div></div><button class="btn sm" data-act="open-req" data-id="${r.id}">فتح</button></div>`).join('') || empty('لا يوجد')}</div></section>
    <section class="card"><h2>طلبات حسب النوع (آخر 12 شهرًا)</h2>${bars(countBy(D.requests.list.filter(r => r.createdAt >= last12), r => r.typeName).slice(0, 10))}</section></div>`;
  } else if (t.cur === 'mgr') {
    const tm = [...teamIds(S.meId)]; const pend = D.requests.list.filter(r => canAct(r));
    const nx = addDays(T, 14); const leaves = D.requests.list.filter(r => tm.includes(r.empId) && r.effect === 'leave' && ['approved', 'pending'].includes(r.status) && r.data?.to >= T && r.data?.from <= nx).sort(by(r => r.data.from));
    const mon = monthly(month, tm);
    body = `<div class="grid g4">${kpi('أعضاء الفريق', fmtN(tm.length))}${kpi('طلبات تحتاج إجرائي', fmtN(pend.length), '', pend.length)}${kpi('في إجازة اليوم', fmtN(tm.filter(id => onLeave(id, T)).length), 'نسبة التغطية: ' + (tm.length ? Math.round((1 - tm.filter(id => onLeave(id, T)).length / tm.length) * 100) : 100) + '%')}${kpi('مرات تأخير الفريق هذا الشهر', fmtN(mon.reduce((a, r) => a + r.late, 0)))}</div>
    <div class="grid g2" style="margin-top:16px"><section class="card"><h2>إجازات الفريق خلال 14 يومًا</h2><div class="list">${leaves.map(r => `<div><div class="grow"><b>${esc(empName(r.empId))}</b><div class="small muted num">${fmtD(r.data.from)} ← ${fmtD(r.data.to)}</div></div>${badge(r.status)}</div>`).join('') || empty('لا توجد إجازات قادمة')}</div></section>
    <section class="card"><h2>استثناءات الحضور هذا الشهر</h2>${mon.filter(r => r.absent || r.late).length ? `<div class="list">${mon.filter(r => r.absent || r.late).map(r => `<div><div class="grow">${esc(r.name)}</div><span class="small">غياب ${r.absent} · تأخير ${r.late}</span></div>`).join('')}</div>` : empty('لا توجد استثناءات')}</section></div>`;
  } else if (t.cur === 'adm') {
    const a = D.requests.list.filter(r => r.category === 'admin'); const open = a.filter(r => r.status === 'pending');
    body = `<div class="grid g4">${kpi('طلبات مفتوحة', fmtN(open.length))}${kpi('متأخرة عن الموعد', fmtN(open.filter(r => r.targetDate && r.targetDate < T).length), '', 1)}${kpi('عهد مسلّمة', fmtN(D.assets.list.filter(x => x.status === 'assigned').length))}${kpi('متوسط زمن الإنجاز', cycleHours(a) == null ? '—' : fmtN(cycleHours(a) / 24, 1) + ' يوم')}</div>
    <div class="grid g2" style="margin-top:16px"><section class="card"><h2>المفتوحة حسب التصنيف</h2>${bars(countBy(open, r => r.typeName))}</section><section class="card"><h2>المفتوحة حسب المسؤول</h2>${bars(countBy(open, r => r.assignedTo ? empName(r.assignedTo) : 'غير مسند'))}</section></div>`;
  }
  return pageHead('التقارير ولوحات المؤشرات', 'كل مؤشر يوضح معادلته أسفل الرقم، ومصدره بيانات المنصة الفعلية') + t.html + body;
};

/* ============ NOTIFICATIONS & SEARCH ============ */
VIEWS.notifications = () => {
  const mine = D.notifications.list.filter(n => n.to === S.meId); const al = computedAlerts();
  return pageHead('الإشعارات', 'إشعارات داخل المنصة. البريد ورسائل الجوال غير مفعلة في هذه النسخة.', mine.some(n => !n.read) ? `<button class="btn" data-act="notes-read">تعليم الكل كمقروء</button>` : '') +
    (al.length ? `<section class="card" style="margin-bottom:16px"><h2>تنبيهات المتابعة <small>محسوبة من تواريخ العقود والوثائق</small></h2><div class="list">${al.map(a => `<div><div class="grow"><b class="small" ${a.bad ? 'style="color:var(--bad)"' : ''}>${esc(a.title)}</b><div class="small muted">${esc(a.body)}</div></div><button class="btn sm ghost" data-act="go" data-v="${a.link.view}" data-id="${a.link.id}">فتح</button></div>`).join('')}</div></section>` : '') +
    `<section class="card"><div class="list">${mine.map(n => `<div><div class="grow"><b class="small">${esc(n.title)}</b>${n.read ? '' : ' <span class="badge b-info">جديد</span>'}<div class="small">${esc(n.body)}</div><div class="small muted num">${fmtDT(n.at)}</div></div>${n.link ? `<button class="btn sm ghost" data-act="open-note" data-id="${n.id}">فتح</button>` : ''}</div>`).join('') || empty('لا توجد إشعارات')}</div></section>`;
};
VIEWS.search = () => {
  const q = (S.params.gq || '').toLowerCase(); if (!q) return empty('اكتب كلمة للبحث');
  const emps = D.employees.list.filter(e => canViewEmp(e.id) && [e.nameAr, e.nameEn, e.empNo, e.title, e.phone].join(' ').toLowerCase().includes(q));
  const reqs = D.requests.list.filter(r => canViewReq(r) && [r.ref, r.typeName, empName(r.empId)].join(' ').toLowerCase().includes(q));
  const fs = (can('forms.manage') ? D.forms.list : visibleForms()).filter(f => [f.title, f.code, f.keywords].join(' ').toLowerCase().includes(q));
  const ships = can('customs.view') ? D.shipments.list.filter(s => [s.ref, s.supplier, s.blNo, s.poNo, s.goods].join(' ').toLowerCase().includes(q)) : [];
  const sec = (t, rows) => `<section class="card" style="margin-bottom:14px"><h2>${t} <small>${rows.length}</small></h2><div class="list">${rows.join('') || empty('لا نتائج')}</div></section>`;
  return pageHead('نتائج البحث عن «' + S.params.gq + '»', 'النتائج حسب صلاحياتك فقط') +
    sec('الموظفون', emps.slice(0, 30).map(e => `<div><div class="grow"><b>${esc(e.nameAr)}</b> <span class="small muted">${esc(e.title || '')} · ${esc(e.empNo)}</span></div><button class="btn sm ghost" data-act="go" data-v="employee" data-id="${e.id}">الملف</button></div>`)) +
    sec('الطلبات', reqs.slice(0, 30).map(r => `<div><div class="grow"><b class="num">${esc(r.ref)}</b> ${esc(r.typeName)} <span class="small muted">${esc(empName(r.empId))}</span></div>${badge(r.status)}<button class="btn sm ghost" data-act="open-req" data-id="${r.id}">فتح</button></div>`)) +
    (can('customs.view') ? sec('الشحنات الواردة', ships.slice(0, 30).map(s => `<div><div class="grow"><b class="num">${esc(s.ref)}</b> ${esc(s.supplier)} <span class="small muted">${esc(s.goods || '')}</span></div>${stageBadge(s)}<button class="btn sm ghost" data-act="open-ship" data-id="${s.id}">فتح</button></div>`)) : '') +
    sec('النماذج والسياسات', fs.slice(0, 30).map(f => `<div><div class="grow"><b>${esc(f.title)}</b> <span class="small muted">${esc(f.code)}</span></div>${badge(f.status)}<button class="btn sm ghost" data-act="open-form" data-id="${f.id}">عرض</button></div>`));
};

/* ============ SETTINGS ============ */
const UNIT_TYPES = { dept: 'إدارة', section: 'قسم', location: 'موقع عمل', costcenter: 'مركز تكلفة' };
const FIELD_TYPES = { text: 'نص', textarea: 'نص طويل', number: 'رقم', date: 'تاريخ', time: 'وقت', month: 'شهر', select: 'قائمة اختيار', leaveType: 'نوع إجازة', course: 'دورة تدريبية', employee: 'موظف', payElement: 'عنصر أجر', personalField: 'حقل بيانات شخصية', asset: 'أصل/عهدة', form: 'نموذج' };
const EFFECTS = { '': 'بدون أثر تلقائي', leave: 'خصم من رصيد الإجازة', permission: 'استئذان (يُسجل فقط)', attendanceFix: 'تصحيح سجل الحضور', letter: 'إصدار خطاب من قالب', finChange: 'تحديث عنصر أجر', personalUpdate: 'تحديث بيانات الموظف', loan: 'إنشاء سلفة', resignation: 'بدء إجراءات إنهاء الخدمة', training: 'تسجيل في دورة' };
function legacySettings(cur) {
  const sm = can('settings.manage'), wf = can('settings.workflow');
  const items = [...(sm ? [['org', 'الهيكل التنظيمي'], ['users', 'المستخدمون والأدوار'], ['matrix', 'مصفوفة الصلاحيات']] : []), ...(sm ? [['cfields', 'إضافة بنود للشاشات'], ['screens', 'شاشات جديدة'], ['lists', 'القوائم']] : []), ...(wf ? [['types', 'النماذج الإلكترونية والمسارات'], ['leaves', 'أنواع الإجازات'], ['tpl', 'قوالب الخطابات']] : []), ...(sm ? [['general', 'إعدادات عامة'], ['integ', 'التكاملات']] : []), ...(can('audit.view') ? [['audit', 'سجل التدقيق']] : []), ...(can('backup') ? [['backup', 'النسخ الاحتياطي']] : [])];
  const t = { cur }; let body = '';
  if (t.cur === 'org') body = dataTable('units', [{ k: 'code', l: 'الرمز' }, { k: 'name', l: 'الاسم' }, { k: 'type', l: 'النوع', s: u => UNIT_TYPES[u.type], v: u => esc(UNIT_TYPES[u.type]) }, { k: 'parent', l: 'يتبع', s: u => unitName(u.parentId), v: u => u.parentId ? esc(unitName(u.parentId)) : '—' }, { k: 'mgr', l: 'المدير', s: u => empName(u.managerId), v: u => u.managerId ? esc(empName(u.managerId)) : '—' }, { k: 'n', l: 'الموظفون', s: u => D.employees.list.filter(e => [e.deptId, e.sectionId, e.locationId, e.costCenterId].includes(u.id)).length, v: u => `<span class="num">${D.employees.list.filter(e => [e.deptId, e.sectionId, e.locationId, e.costCenterId].includes(u.id) && e.status !== 'terminated').length}</span>` }, { k: 'x', l: '', nosort: true, v: u => `<button class="btn sm ghost" data-act="unit-edit" data-id="${u.id}">تعديل</button>` }], D.orgunits.list.sort(by(u => u.type + u.name)), { tools: `<button class="btn sm pri" data-act="unit-edit">${ic('plus')} وحدة جديدة</button>` });
  else if (t.cur === 'users') body = `<div class="note" style="margin-bottom:10px">دورا «المدير المباشر» و«مدير الإدارة» يُستنتجان تلقائيًا من الهيكل التنظيمي. هنا تُسند الأدوار الوظيفية الأخرى، وكل تغيير يُسجل في سجل التدقيق.</div>` + dataTable('users', [{ k: 'empNo', l: 'الرقم' }, { k: 'nameAr', l: 'الموظف' }, { k: 'dept', l: 'الإدارة', s: e => unitName(e.deptId), v: e => esc(unitName(e.deptId)) }, { k: 'roles', l: 'الأدوار', s: e => [...rolesOf(e)].join(), v: e => [...rolesOf(e)].map(r => `<span class="tag">${esc(ROLES[r])}</span>`).join('') }, { k: 'x', l: '', nosort: true, v: e => `<button class="btn sm" data-act="user-access" data-id="${e.id}">الأدوار</button>` }], D.employees.list.filter(e => e.status !== 'terminated').sort(by('empNo')));
  else if (t.cur === 'matrix') { const m = MATRIX(); body = `<div class="note warn" style="margin-bottom:10px">في هذه النسخة تُفرض الصلاحيات داخل التطبيق. فرضها على الخادم وقاعدة البيانات حسب الدور يحتاج النسخة الإنتاجية (انظر تبويب التكاملات).</div><form data-form="matrix"><div class="tablewrap"><table><thead><tr><th>الصلاحية</th>${Object.keys(ROLES).map(r => `<th>${esc(ROLES[r])}</th>`).join('')}</tr></thead><tbody>${Object.entries(PERMS).map(([p, l]) => `<tr><td>${esc(l)}</td>${Object.keys(ROLES).map(r => `<td style="text-align:center"><input type="checkbox" name="${r}[]" value="${p}" ${(m[r] || []).includes(p) ? 'checked' : ''} aria-label="${esc(ROLES[r] + ' — ' + l)}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="row" style="margin-top:10px"><button class="btn pri">حفظ المصفوفة</button><button class="btn" type="button" data-act="matrix-reset">استعادة الافتراضي</button></div></form>`; }
  else if (t.cur === 'cfields') body = cfSettingsHtml();
  else if (t.cur === 'screens') body = screensSettingsHtml();
  else if (t.cur === 'lists') body = listsSettingsHtml();
  else if (t.cur === 'types') body = dataTable('rtypes', [{ k: 'code', l: 'الرمز' }, { k: 'name', l: 'نوع الطلب' }, { k: 'category', l: 'التصنيف', s: x => CATS[x.category], v: x => esc(CATS[x.category] || '') }, { k: 'fields', l: 'الحقول', s: x => (x.fields || []).length, v: x => `<span class="num">${(x.fields || []).filter(f => f.type !== 'section').length}</span>` }, { k: 'stages', l: 'خط سير الموافقات', s: x => (x.stages || []).length, v: x => `<span class="small">${['مقدم الطلب', ...(x.stages || []).map(s => s.name)].map(esc).join(' ← ')}</span>` }, { k: 'effect', l: 'الأثر', v: x => esc(EFFECTS[x.effect || '']) }, { k: 'active', l: 'الحالة', v: x => x.active === false ? badge('cancelled', 'معطل') : badge('approved', 'مفعل') }, { k: 'x', l: '', nosort: true, v: x => `<button class="btn sm ghost" data-act="dz-open" data-id="${x.id}">${ic('file')} تصميم</button>` }], D.requestTypes.list.sort(by('order')), { tools: `<button class="btn sm pri" data-act="dz-open">${ic('plus')} تصميم نموذج جديد</button>` });
  else if (t.cur === 'leaves') body = `<div class="note warn" style="margin-bottom:10px">الاستحقاقات المسجلة قيم مبدئية تحتاج مراجعة مع سياسة الشركة ونظام العمل السعودي.</div>` + dataTable('ltypes', [{ k: 'name', l: 'نوع الإجازة' }, { k: 'annualDays', l: 'الاستحقاق السنوي', v: l => l.tracked === false ? 'بدون رصيد' : `<span class="num">${l.annualDays}</span>` }, { k: 'paid', l: 'مدفوعة', v: l => l.paid ? 'نعم' : 'لا' }, { k: 'x', l: '', nosort: true, v: l => `<button class="btn sm ghost" data-act="lt-edit" data-id="${l.id}">تعديل</button>` }], D.leaveTypes.list.sort(by('order')), { search: false, tools: `<button class="btn sm pri" data-act="lt-edit">${ic('plus')} نوع إجازة</button>` });
  else if (t.cur === 'tpl') body = `<div class="note" style="margin-bottom:10px">المتغيرات المتاحة: {{name}} {{nameEn}} {{empNo}} {{title}} {{dept}} {{location}} {{nationality}} {{hireDate}} {{joinDate}} {{basic}} {{total}} {{date}} {{ref}} {{addressee}} {{purpose}} {{company}}</div>` + dataTable('tpls', [{ k: 'name', l: 'القالب' }, { k: 'kind', l: 'النوع' }, { k: 'x', l: '', nosort: true, v: x => `<button class="btn sm ghost" data-act="tpl-edit" data-id="${x.id}">تعديل</button>` }], D.templates.list, { search: false, tools: `<button class="btn sm pri" data-act="tpl-edit">${ic('plus')} قالب جديد</button>` });
  else if (t.cur === 'general') { const s = SET(); body = `<form class="form card" data-form="general">${fld('company', 'اسم المنشأة', { value: s.company, required: true })}${fld('contractAlertDays', 'التنبيه قبل انتهاء العقود والوثائق (أيام)', { type: 'number', value: s.contractAlertDays ?? 60, min: 1 })}${fld('defaultSla', 'المدة المستهدفة الافتراضية لكل مرحلة (ساعات)', { type: 'number', value: s.defaultSla ?? 48, min: 1 })}${fld('demoMode', 'شريط بيئة العرض', { type: 'checkbox', value: s.demoMode !== false, cbLabel: 'إظهار تنبيه أن البيانات تجريبية' })}<div class="fld full"><button class="btn pri" style="align-self:flex-start">حفظ</button></div></form>`; }
  else if (t.cur === 'integ') body = `<div class="grid g2">${[['SAP Business One', 'غير منفذ', 'bad', 'يحتاج قبل التنفيذ: تحديد الحقول ونظامها المرجعي (مراكز التكلفة والقيود من SAP، بيانات الموظفين من المنصة)، اتجاه وتكرار المزامنة، الوصول إلى Service Layer وترخيصه، وبيئة خادم وسيطة. لا يمكن تنفيذه من داخل هذه النسخة.'], ['أجهزة البصمة', 'استيراد ملف Excel', 'warn', 'الربط المباشر يحتاج واجهة برمجية من مورد الجهاز وخادمًا وسيطًا. المتاح الآن: تصدير الحركات من برنامج البصمة إلى Excel أو CSV واستيرادها من صفحة الحضور مع معاينة قبل الحفظ.'], ['منصة فسح (الزكاة والضريبة والجمارك)', 'غير منفذ', 'bad', 'حالة البيان الجمركي تُحدّث يدويًا في وحدة التخليص بناءً على ما يبلغه المخلص. لا يوجد ربط آلي مع فسح.'], ['البريد الإلكتروني', 'غير منفذ', 'bad', 'يحتاج خادم بريد SMTP أو خدمة مثل Microsoft 365 ونطاق الشركة. الإشعارات حاليًا داخل المنصة فقط.'], ['رسائل الجوال SMS', 'غير منفذ', 'bad', 'يحتاج مزود رسائل مرخص في المملكة (اسم مرسل معتمد) وتكلفة لكل رسالة.'], ['التوقيع الإلكتروني', 'غير منفذ', 'bad', 'الإقرارات الحالية تسجل هوية المستخدم ووقت الإقرار فقط، وليست توقيعًا إلكترونيًا معتمدًا نظاميًا.'], ['الدخول الموحد SSO', 'غير منفذ', 'bad', 'الدخول الحالي اختيار هوية الموظف داخل بيئة العرض. الإنتاج يحتاج Microsoft Entra ID أو ما يعادله.'], ['فرض الصلاحيات على الخادم', 'جزئي', 'warn', 'قاعدة البيانات الحالية تحمي البيانات حسب مستوى مشاركة الصفحة (عرض/مساهمة/تحرير)، أما أدوار الموارد البشرية العشرة فتُفرض داخل التطبيق. الفرض الكامل على الخادم وواجهات API يحتاج النسخة الإنتاجية.']].map(([n, s, c, d]) => `<section class="card"><h2>${n} ${badge(c === 'bad' ? 'rejected' : 'returned', s)}</h2><p class="small" style="margin:0">${d}</p></section>`).join('')}</div>`;
  else if (t.cur === 'audit') body = dataTable('audit', [{ k: 'at', l: 'التاريخ والوقت', v: a => `<span class="num">${fmtDT(a.at)}</span>` }, { k: 'byName', l: 'المستخدم' }, { k: 'action', l: 'الإجراء' }, { k: 'entity', l: 'الكيان' }, { k: 'detail', l: 'التفاصيل' }], D.audit.list, { tools: `<span class="small muted">آخر 600 حدث</span>${can('export.data') ? `<button class="btn sm" data-act="export-audit">${ic('down')} تصدير</button>` : ''}` });
  else if (t.cur === 'backup') body = `<div class="grid g2"><section class="card"><h2>نسخة احتياطية</h2><p class="small">تنزيل ملف JSON بكل مجموعات البيانات (عدا الملفات المرفوعة، فهي محفوظة في مخزن الأصول). احفظه في مكان آمن لأنه يحتوي بيانات حساسة.</p><button class="btn pri" data-act="backup">${ic('down')} تنزيل النسخة الاحتياطية</button></section><section class="card"><h2>الاستعادة</h2><p class="small">تستبدل السجلات الموجودة بنفس المعرف وتضيف المفقود. لا تحذف السجلات غير الموجودة في الملف.</p><input type="file" id="restore-file" accept=".json" aria-label="ملف النسخة الاحتياطية"><div style="margin-top:8px"><button class="btn danger" data-act="restore">استعادة من الملف</button></div></section></div>`;
  return body;
}
